function DrawView:ctor(parents,groupId)
    local csbPath = "hall/res/FriendScircle/drawView/drawView.csb"
    DrawView.super.ctor(self, csbPath)
    self:enableMask(true)
    GameUtils.setNodeNameBindObj(self._csbNode)
    self.parents = parents
    self.family_id = groupId
    self.rateOrConstant = nil

    self:initUI()
    self:initEvent()
    self:initGameDataDraw()
end

function DrawView:initUI()
    self.btn_1:hide()
    self.btn_1:setContentSize(self.btn_1.btn:getContentSize())
    self.btn_2:hide()
    self.content_vw.content_9.listViewText:hide()
    self.content_vw.content_8.listViewText:hide()
    self.content_vw.content_10:hide()
    self.content_vw.content_11:hide()
    self.btn_set = self.content_vw.content_10.btn_set
    self:set_content_11( true )
    self.listViewTal:setScrollBarEnabled(false)
    if isShowStartCost then
        self.content_vw.content_12:show()
    else
        self.content_vw.content_12:hide()
    end
end

function DrawView:set_content_11( flag )
    if isShowQuJian then
        self.content_vw.content_10:setVisible(flag)
        if flag == true then
            self.rateOrConstant = 3 
        else 
            self.rateOrConstant = 1
        end
    else
        self.content_vw.content_11:setVisible(flag)
        if flag == true then
            self.rateOrConstant = 2
        else 
            self.rateOrConstant = 1
        end
    end
end

function DrawView:initEvent()
    self.btnClose:onClick(handler(self, self.onClickBtnClose), true)
    self.btn_sure:onClick(handler(self, self.onClickBtnComint), true)
    self.btn_set:onClick(handler(self, self.onClickBtnSet), true)
end

function DrawView:onClickBtnClose()
    self:removeSelf()
end

function DrawView:onClickBtn1( event )
    local target = event.target
    local value = target.value
    local parant = target:getParent():getParent()
    for k,node in ipairs(parant:getChildren()) do
        node.btn:setEnabled(true)
        local size = node.btn:getContentSize()
        node:setContentSize(size)
        node.btn:setPosition(size.width / 2, size.height / 2)
        for key,node1 in ipairs(node:getChildren()) do
            if node1:getName() ~= "btn" then
                node1:removeSelf()
            end
        end
    end
    local btn_1 = target:getChildByName("btn")
    target:setEnabled(false)
    self:labelLayout(value, target:getParent())
end

function DrawView:onClickBtn2( event )
    local target = event.target
    local value = target.value or {}
    local parant = target:getParent():getParent()
    for key,node1 in ipairs(parant:getChildren()) do
        if node1:getName() ~= "btn" then
            node1.btn:setEnabled(true)
        end
    end
    target:setEnabled(false)
    self:partakeLayout(value)
    self:baseAndOutChip(value)
    self:giveAndWin(value)
    self:ptScore(value)
    self:additionalLayout(value)
    self:setQuJian(value.gameConfig.secConstant)
    self.qujianStr = value.gameConfig.secConstant or ""
    tempList = value
    self.content_vw.content_9.listViewText:hide()
    self.content_vw.content_8.listViewText:hide()
end

function DrawView:onClickBtnSet( event )
    -- local data = event.target.data
    local Section = Section.new(self.qujianStr, handler(self, self.setQuJian))
    Section:addTo(self)
end

function DrawView:setQuJian( qujianStr )
    qujianStr = qujianStr or ""
    self.qujianStr = qujianStr
    local arrStr = string.split(qujianStr, ",")
    local str = arrStr[1]
    local strs = string.split(str, "-")
    if strs[2] then
        local newStrs = ""
        for i,v in ipairs(strs) do
            v = tonumber(v) or 0
            v = v / 100
            if newStrs == "" then
                newStrs = v
            else
                newStrs = newStrs .. "-" .. v
            end
        end
        str = newStrs
    end

    dump(self.qujianStr,"-------self.qujianStr")
    self.content_vw.content_10.txt:setString(str)
end

function DrawView:initGameDataDraw()
    local gameNameList = {}
    local firstBtn = nil
    for k, value in pairs(self.parents.gameConfigList) do
        for k2, v2 in pairs(value) do
            if next(v2) then
                gameNameList[k] = v2.level
                break
            end
        end
    end
    for k, value in pairs(self.parents.gameConfigList) do
        if gameNameList[k] then
            local btn_1 = self.btn_1:clone()
            btn_1:show()
            GameUtils.setNodeNameBindObj(btn_1)
            local btn = btn_1.btn
            self.listViewTal:pushBackCustomItem(btn_1)
            local name = GetGameName:getName(gameNameList[k])
            btn:setTitleText(name)
            btn:setEnabled(true)
            btn.value = value
            btn:onClick(handler(self, self.onClickBtn1))
            if firstBtn == nil then
                firstBtn = btn
            end
        end
    end
    self.listViewTal:requestDoLayout()
    self:onClickBtn1( {target = firstBtn} )
end

function DrawView:labelLayout(list, btn_1)
    if list and next(list) then
        local countList = 0
        for k2, v2 in pairs(list or {}) do
            if v2.name ~= nil then
                countList = countList + 1
            end
        end
        local firstBtn = nil

        local index = 1
        local btn1Height = 71
        local btn2Height = 73
        local height = btn2Height * countList + btn1Height
        local initY = height - btn1Height / 2
        btn_1:setContentSize(220.00, height)
        btn_1.btn:setPositionY(initY)
        
        for k2, v2 in pairs(list or {}) do
            dump(v2,"gameList==")
            if v2.name ~= nil then
                local btn_2 = self.btn_2:clone()
                GameUtils.setNodeNameBindObj(btn_2)
                btn_1:addChild(btn_2)
                btn_2:show()
                btn_2:setPosition(0, initY - index * btn2Height)
                local btn = btn_2.btn
                local name = require("hall.GameCommon"):formatNick(v2.name or " ")
                btn:setTitleText(name)
                if firstBtn == nil then
                    tempList = v2
                    firstBtn = btn
                end
                btn.value = v2
                index = index + 1
                btn:onClick(handler(self, self.onClickBtn2))
            end
        end
        self:onClickBtn2( {target = firstBtn} )
        self.listViewTal:requestDoLayout()
        local index = self.listViewTal:getIndex(btn_1)
        self.listViewTal:jumpToItem(index,cc.p(1, 1), cc.p(1, 1))
    end
end

-- 平摊模式
function DrawView:ptScore(data)
    if data  then
        if data.gameConfig.oneOrAll == nil then
            data.gameConfig.oneOrAll = 2
        end
        local checkBoxTemp = self.content_vw.content_5.radio_1.checkBox
        checkBoxTemp.select = false
        checkBoxTemp:setSelectedState(false)
        checkBoxTemp.isCheck = 0
        checkBoxTemp.oneOrAll = 2
        if data.gameConfig.oneOrAll == 2 then
            checkBoxTemp.select = true
            checkBoxTemp:setSelectedState(true)
            checkBoxTemp.isCheck = 1
            oneOrAll = 2
        end
        self:toAddListenerCheckBox3(checkBoxTemp)

        local checkBoxTemp2 = self.content_vw.content_5.radio_2.checkBox
        checkBoxTemp2.select = false
        checkBoxTemp2:setSelectedState(false)
        checkBoxTemp2.isCheck = 0
        checkBoxTemp2.oneOrAll = 1
        if data.gameConfig.oneOrAll == 1 then
            checkBoxTemp2.select = true
            checkBoxTemp2:setSelectedState(true)
            checkBoxTemp2.isCheck = 1
            checkBoxTemp2.oneOrAll = 1
            oneOrAll = 1
        end
        self:toAddListenerCheckBox3(checkBoxTemp2)
    end
end

