---倍率与淘汰分
function DrawView:baseAndOutChip(data)
    if data then
        dump(data.gameConfig.baseChip,"data.gameConfig.baseChip")
        local base = 10
        if type(data.gameConfig.baseChip) == "table" then
            base = data.gameConfig.baseChip.optionValue
        elseif type(data.gameConfig.baseChip) == "number" then
            base = data.gameConfig.baseChip
        end
        local txt = self.content_vw.content_4.txt:setString(base)---倍率
        self.content_vw.content_4.txt:setString(base)
        self.content_vw.content_4.bt_del_num:onClick(function( event )
            local value = tonumber(txt:getString())
            if value and value > 1 then
                txt:setString(value - 1)
            else
                txt:setString(1)
            end
        end)
        self.content_vw.content_4.bt_add_num:onClick(function( event )
            local value = tonumber(txt:getString())
            if value then
                txt:setString(value + 1)
            else
                txt:setString(1)
            end
        end)

        ---淘汰分
        if data.gameConfig.readyPoint == nil then
            data.gameConfig.readyPoint = 2000
        end
        self.content_vw.content_2.txt:setString(data.gameConfig.readyPoint/100)

        -- 台费
        if data.gameConfig.startCost then
            self.content_vw.content_12.txt:setString(data.gameConfig.startCost/100)
        else
            self.content_vw.content_12.txt:setString(0)
        end


        if data.gameConfig.juLi and data.gameConfig.juLi then
            if type(data.gameConfig.juLi) == "number" then
                self.content_vw.content_13.txt:setString(data.gameConfig.juLi)
            else
                self.content_vw.content_13.txt:setString(data.gameConfig.juLi.optionValue)    
            end
        else
            self.content_vw.content_13.txt:setString(0)
        end

        self:newEditBox2Float(self.content_vw.content_13.txt)
        
        self:newEditBox2Float(self.content_vw.content_2.txt)
    end

end

--积分赠送
function DrawView:giveAndWin(data)
    self.content_vw.content_8.listViewText:removeAllChildren()
    self.content_vw.content_9.listViewText:removeAllChildren()

    if data then
        local content_8 = self.content_vw.content_8--积分赠送
        local txt = self.content_vw.content_8.txt--积分赠送
        local str = ""
        profitType = data.gameConfig.profitType
        if profitType == 0 then
            str = "所有赢家"
        else
            if profitType == nil then
                profitType = 0
            end
            str = profitType.."个大赢家"
        end
        txt:setString(str)
        content_8.text_bg:onClick(function (event)
            local listViewText = self.content_vw.content_8.listViewText
            listViewText:setVisible(not listViewText:isVisible())
        end)
        for i = 0, 3 do
            local text_clone = self.text_clone:clone()
            if i == 0 then
                text_clone:getChildByName("text"):setString("所有赢家")
            else
                text_clone:getChildByName("text"):setString(i.."个赢家")
            end
            text_clone:onClick(function (event)
                local target = event.target:getChildByName("text")
                profitType = i
                txt:setString(target:getString())
                content_8.listViewText:setVisible(false)
            end)
            content_8.listViewText:pushBackCustomItem(text_clone)
        end


        local content_9 = self.content_vw.content_9--积分赠送
        local txt = content_9.txt--积分赠送
        txt:setString("固定")
        
        if isShowDianWei then
            self:set_content_11( true )
        else
            content_9.text_bg:onClick(function (event)
                local listViewText = self.content_vw.content_9.listViewText
                listViewText:setVisible(not listViewText:isVisible())
            end)
            for i = 0, 10 do
                local text_clone = self.text_clone:clone()
                if i == 0 then
                    text_clone:getChildByName("text"):setString("固定")
                else
                    text_clone:getChildByName("text"):setString("赠送"..i)
                end
                text_clone:onClick(function (event)
                    local target = event.target:getChildByName("text")
                    local str = "固定"
                    self:set_content_11( true )
                    if i > 0 then
                        self:set_content_11( false )
                        str = "赠送"..i.."次"
                        profit = i
                    end
                    txt:setString(target:getString())
                    content_9.listViewText:setVisible(false)
                end)
                content_9.listViewText:pushBackCustomItem(text_clone)
            end
            if data.gameConfig.rateOrConstant == nil then
                data.gameConfig.rateOrConstant = 1
            end
            if data.gameConfig.rateOrConstant == 2 or data.gameConfig.rateOrConstant == 3 then
                self:set_content_11( true )
            else
                if data.gameConfig.profit == nil then
                    data.gameConfig.profit = 1
                end
                txt:setString("赠送积分"..data.gameConfig.profit .."次")
                self:set_content_11( false )
            end
        end

        profit = data.gameConfig.profit
        self.rateOrConstant = data.gameConfig.rateOrConstant
        if data.gameConfig.profit == nil then
            data.gameConfig.profit = 0
        end
        local txt = self.content_vw.content_11.txt
        if PROFIT_MUL_100_2SERVER then
            txt:setString(profit / 100)
            self:newEditBox2Float(txt)
        else
            txt:setString(profit)
            self:newEditBox(txt)
        end

        local txt = self.content_vw.content_7.txt--起抽
        if data.gameConfig.profitLimit == nil then
            data.gameConfig.profitLimit = 5000
        end
        txt:setString(data.gameConfig.profitLimit/100)
        self:newEditBox(txt)
        
        local txt = self.content_vw.content_12.txt--台费
        txt:setString((data.gameConfig.startCost or 0)/100)
        self:newEditBox2Float(txt)
    end
end


function DrawView:toAddListenerCheckBox3(checkNode)
    checkNode:addEventListenerCheckBox(function(sender,eventType)
        require("hall.GameCommon"):onClickSound()
        if eventType == CHECKBOX_STATE_EVENT_SELECTED then
            for idx = 1, 2 do
                local radio = self.content_vw.content_5["radio_"..idx]
                local checkBox = radio.checkBox
                if checkBox.isCheck == 1 then
                    checkBox:setSelectedState(false)
                    checkBox.select = false
                    checkBox.isCheck = 0
                end
            end
            sender.isCheck = 1
            sender:setSelectedState(true)
            sender.select = false
            oneOrAll = sender.oneOrAll
        elseif eventType == CHECKBOX_STATE_EVENT_UNSELECTED then
            dump("gfffffffffffffffff")
            sender.select = true
            sender:setSelectedState(true)
        end
    end)
end

function DrawView:onClickBtnComint()
    local content_1 = tonumber(self.content_vw.content_1.txt:getString()) or 50--参与分
    local content_2 = tonumber(self.content_vw.content_2.txt:getString()) or 20--淘汰法
    local content_4 = tonumber(self.content_vw.content_4.txt:getString()) or 10--倍率
    local content_6 = tonumber(self.content_vw.content_6.txt:getString()) or 0--额外赠送
    local content_7 = tonumber(self.content_vw.content_7.txt:getString()) or 0--起抽
    local content_8 = tonumber(self.content_vw.content_8.txt:getString()) or 0--积分赠送
    local content_9 = tonumber(self.content_vw.content_9.txt:getString())--赠送设置 几个赢家
    local content_11 = tonumber(self.content_vw.content_11.txt:getString())--固定多少分
    local content_12 = tonumber(self.content_vw.content_12.txt:getString()) or 0--台费
    local content_13 = tonumber(self.content_vw.content_13.txt:getString()) or 0--距离限制

    if isShowDianWei then
        self.rateOrConstant = 2
    end
    if self.rateOrConstant == 2 then  --积分赠送
        tempList.gameConfig.profit = content_11
        if PROFIT_MUL_100_2SERVER then
            tempList.gameConfig.profit = math.floor(content_11 * 100)
        end
    else
        tempList.gameConfig.profit = profit
    end
    tempList.gameConfig.rateOrConstant = self.rateOrConstant--积分赠送
    tempList.gameConfig.profitType = profitType  --所有赢家还是 几个赢家
    tempList.gameConfig.oneOrAll = oneOrAll or 2 --模式

    tempList.gameConfig.profitLimit = content_7 * 100--起抽
    tempList.gameConfig.baseChip = content_4--倍率
    tempList.gameConfig.readyPoint = content_2 * 100--淘汰分
    tempList.gameConfig.joinGamePoint = content_1 * 100--参与分
    tempList.gameConfig.additionalPoint = content_6 * 100--额外赠送

    tempList.gameConfig.secConstant = self.qujianStr--额外赠送
    tempList.gameConfig.juLi = content_13  --距离限制

    if content_12 and content_12 >= 0 then
        tempList.gameConfig.startCost = content_12 * 100--台费赠送
    end

    dump(oneOrAll,"oneOrAll--")
    FamilyData:updateGameConfig(tempList.gameConfig , self.parents.family_id, tempList.id,handler(self , self.RemoveCreate))
end

function DrawView:RemoveCreate()
    dump(tempList.gameConfig.profit)
    if not tolua.isnull(self.parents) then
        self.parents.gameConfigList[tempList.gameType][tempList.id] = tempList
    end
end

function DrawView:newEditBox(node, maxLength, string)
    self:newTextField(node, maxLength, string)
    do
        return
    end
    string = string or node:getString()
    maxLength = maxLength or 10
  
    local params = {
        size = node:getContentSize(),
        -- fontSize = node:getFontSize(),
        fontSize = 1,
        fontColor = node:getTextColor(),
        maxLength = maxLength,
        inputMode = cc.EDITBOX_INPUT_MODE_NUMERIC,
        -- placeHolder = string,
    }
    local editBox = ccs.newEditBox(params)
    node:getParent():addChild(editBox)
    editBox:setAnchorPoint(node:getAnchorPoint())
    editBox:setPosition(node:getPosition())
    local idx = editBox:getLocalZOrder()
    editBox:setLocalZOrder(-99)
    editBox:setText(node:getString())
    editBox:registerScriptEditBoxHandler(function( strEventName,sender )
        if strEventName == "began" then--光标进入，选中全部内容
            sender:setText("")
            node:setString("")
        elseif strEventName == "ended" then--当编辑框失去焦点并且键盘消失的时候被调用
            local num = tonumber(sender:getText()) or 0
            num = math.floor(num)
            if num < 0 then
                num = 0
            end
            sender:setText(num)
            node:setString(num)
        elseif strEventName == "return" then--当用户点击编辑框的键盘以外的区域，或者键盘的Return按钮被点击时所调用
        elseif strEventName == "changed" then--输入内容改变时调用
            local num = tonumber(sender:getText()) or 0
            num = math.floor(num)
            if num < 0 then
                num = 0
            end
            node:setString(num)

            --sender:setText(num)
            --node:setString(num)
        end
    end)
end

function DrawView:newTextField(node, maxLength, string)
    string = string or node:getString()
    maxLength = maxLength or 10
    local params = {
        size = node:getContentSize(),
        fontSize = node:getFontSize(),
        fontColor = node:getTextColor(),
        maxLength = maxLength,
        placeHolder = string,
    }
    local textField =  node:getParent():getChildByName("textField")
    if textField then
        textField:removeSelf()
    end
    node:hide()
    local textField = ccs.textField(params)
    textField:setName("textField")
    textField:setContentSize(node:getContentSize())
    node:getParent():addChild(textField)
    textField:setAnchorPoint(node:getAnchorPoint())
    textField:setPosition(node:getPosition())
    textField:setTextColor(node:getTextColor())
    textField:setText(node:getString())
    textField:setTouchSize(node:getContentSize())
    textField:setTouchAreaEnabled(true)
    textField:addEventListener(function(sender,event)
        if event == ccui.TextFiledEventType.attach_with_ime then
            --光标进入
        elseif event == ccui.TextFiledEventType.detach_with_ime then
            --光标离开 关闭键盘
            local num = tonumber(sender:getString()) or 0
            num = math.floor(num)
            if num < 0 then
                num = 0
            end
            sender:setText(num)
            node:setString(num)
        elseif event == ccui.TextFiledEventType.insert_text then
            --输入
            local num = tonumber(sender:getString()) or 0
            num = math.floor(num)
            if num < 0 then
                num = 0
            end
            sender:setText(num)
            node:setString(num)
        elseif event == ccui.TextFiledEventType.delete_backward then
             --删除
             local num = tonumber(sender:getString()) or 0
            num = math.floor(num)
            if num < 0 then
                num = 0
            end
            sender:setText(num)
            node:setString(num)
        end
    end)
end

function DrawView:newEditBox2Float(node, maxLength, string)
    self:newTextField(node, maxLength, string)
    do
        return
    end
    string = string or node:getString()
    maxLength = maxLength or 10

    local params = {
        size = node:getContentSize(),
        -- fontSize = node:getFontSize(),
        fontSize = 1,
        fontColor = node:getTextColor(),
        maxLength = maxLength,
        inputMode = cc.EDITBOX_INPUT_MODE_ANY,
        -- placeHolder = string,
    }
    local editBox = ccs.newEditBox(params)
    node:getParent():addChild(editBox)
    editBox:setAnchorPoint(node:getAnchorPoint())
    editBox:setPosition(node:getPosition())
    local idx = editBox:getLocalZOrder()
    editBox:setLocalZOrder(-99)
    editBox:setText(node:getString())
    editBox:registerScriptEditBoxHandler(function( strEventName,sender )
        if strEventName == "began" then--光标进入，选中全部内容
            sender:setText("")
            node:setString("")
        elseif strEventName == "ended" then--当编辑框失去焦点并且键盘消失的时候被调用
            local num = tonumber(sender:getText()) or 0
            local tempNum = math.floor(num)
            num = tonumber(string.format("%.2f", num))
            if num == tempNum then
                num = tempNum
            end
            if num < 0 then
                num = 0
            end
            sender:setText(num)
            node:setString(num)
        elseif strEventName == "return" then--当用户点击编辑框的键盘以外的区域，或者键盘的Return按钮被点击时所调用
        elseif strEventName == "changed" then--输入内容改变时调用
            local num = tonumber(sender:getText()) or 0
            local tempNum = math.floor(num)
            num = tonumber(string.format("%.2f", num))
            if num == tempNum then
                num = tempNum
            end
            if num < 0 then
                num = 0
            end
            node:setString(num)

            --sender:setText(num)
            --node:setString(num)
        end
    end)
end

return DrawView